@echo off
if "a" == "a" echo SAME
echo DONE

@echo off
if "" == "selected" echo WRONG
echo DONE

@echo off
setlocal enabledelayedexpansion
set input=1
if !input! EQU 1 (
 echo A
) else if !input! EQU 2 (
 echo B
) else if !input! EQU 3 (
 echo C
) else (
 echo D
)
echo DONE

@echo off
setlocal enabledelayedexpansion
set amount=90
set count=10
if !amount! LSS 0 (
 echo LOW
) else if !count! LSS 1 (
 echo SMALL
)
echo DONE
